31	// ---------------------------------------------------------------------------
32	// Shared memory swizzle: row-major [rows][128] bf16 tile, 256B rows.
33	// Permute the eight 16B granules of each 128B segment by (row & 7) so that
34	// ldmatrix's 8 row addresses (8 consecutive rows, fixed 16B window) hit
35	// distinct banks. Invertible (XOR), preserves 16B alignment.
36	__device__ __forceinline__ int swizzle_off(int row, int col) {
37	    const int byte = row * (HEAD_DIM * 2) + col * 2;
38	    const int gran = (byte >> 4) & 7;
39	    const int sw = (byte >> 4) ^ (row & 7);
40	    return (byte & ~0x70) | (sw << 4) | (byte & 0x0F);
41	}
